import os
from pathlib import Path

def walk(root):
    out = []
    stack = [root]
    while stack:
        d = stack.pop()
        for name in sorted(os.listdir(d)):
            full = d + '/' + name
            if os.path.isdir(full):
                stack.append(full)
            else:
                out.append(full)
    return sorted(out)

